/**
 * Normalizes state or district names for case-insensitive and alias matching
 */
function normalizeName(str) {
  if (!str) return '';
  return String(str)
    .toLowerCase()
    .replace(/\(.*?\)/g, '')
    .replace(/[^a-z0-9]/g, '')
    .trim();
}

/**
 * Lookup subdivisions for a given State and District
 * Supports case-insensitivity, trim, and common aliases
 */
export function getDistrictSubdivisions(stateName, districtName) {
  if (!stateName || !districtName) {
    return { cities: [], mandals: [] };
  }

  const sNorm = normalizeName(stateName);
  const matchedStateKey = Object.keys(PAN_INDIA_DISTRICT_SUBDIVISIONS).find(
    k => normalizeName(k) === sNorm || normalizeName(k).includes(sNorm) || sNorm.includes(normalizeName(k))
  );

  if (!matchedStateKey) {
    return { cities: [districtName], mandals: [districtName + ' Urban', districtName + ' Rural'] };
  }

  const stateObj = PAN_INDIA_DISTRICT_SUBDIVISIONS[matchedStateKey] || {};
  const dNorm = normalizeName(districtName);

  const matchedDistrictKey = Object.keys(stateObj).find(
    k => normalizeName(k) === dNorm || normalizeName(k).includes(dNorm) || dNorm.includes(normalizeName(k))
  );

  if (matchedDistrictKey && stateObj[matchedDistrictKey]) {
    return stateObj[matchedDistrictKey];
  }

  return {
    cities: [districtName, districtName + ' City'],
    mandals: [districtName + ' Urban', districtName + ' Rural']
  };
}

/**
 * Get sorted list of Cities/Towns for a given State and District
 */
export function getAllDistrictCities(stateName, districtName) {
  const { cities } = getDistrictSubdivisions(stateName, districtName);
  return Array.isArray(cities) && cities.length > 0 ? cities : [districtName];
}

/**
 * Get sorted list of Mandals/Tehsils/Taluks for a given State and District
 */
export function getAllDistrictMandals(stateName, districtName) {
  const { mandals } = getDistrictSubdivisions(stateName, districtName);
  return Array.isArray(mandals) && mandals.length > 0 ? mandals : [districtName + ' Urban', districtName + ' Rural'];
}
